fn solve(n: i8, k: i8) -> Vec<i8> {
    // If no items are selected or all items are selected, there are no "good" unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise at least one is unselected and at least one is selected,
    // so the minimum good unselected is 1.
    let x_min = 1;
    // The maximum good unselected is the smaller of:
    //  1) the total number of unselected items (n - k)
    //  2) twice the number of selected items (2 * k)
    let x_max = (n - k).min(2 * k);

    vec![x_min, x_max]
}